// A limit buy over Base's Aerodrome Slipstream, Uniswap V3 and hookless Uniswap V4 pools: up to
// `budget` of `payToken` for `buyToken`, never more than `maxPrice` for any unit, fees included.
//
//   sauce run distributed-swap.sauce.ts --chain <chain> --keystore <keystore> \
//     --fund <payToken>:<budget> --args <payToken> <buyToken> <budget> <maxPrice> <minTokens> \
//     <maxAvgPrice> <recipient> <refundTo>
//
//   payToken: Address     the token paid; the budget must be in the Pot (`--fund` pulls it in)
//   buyToken: Address     the token bought
//   budget: Uint256       the most payToken to spend, in its base units: 1000000000 is 1,000 USDC
//   maxPrice: Uint256     the most one buyToken may cost, fees included: the price in whole tokens
//                         times 10^(18 + payDecimals − buyDecimals)
//   minTokens: Uint256    the least buyToken to receive, in its base units; less reverts the cook
//   maxAvgPrice: Uint256  the most the average may cost, in maxPrice's units; 0 turns it off
//   recipient: Address    receives what is bought
//   refundTo: Address     receives what is left of the budget
//
//   SPCXc (8 decimals) for all of 1,000 USDC (6) or nothing, at most 150 each, 149.25 on average:
//   sauce run distributed-swap.sauce.ts --chain base --keystore <keystore> --fund USDC:1000 \
//     --args 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913 0xb2000000000000000000007b9fcbd005511aCBd5 \
//     1000000000 1500000000000000000 666666667 1492500000000000000 <recipient> <refundTo>
//   WETH (18 decimals) for all of 3,000 USDC or nothing, at most 2,713.5 each, 2,706.75 on average:
//   sauce run distributed-swap.sauce.ts --chain base --keystore <keystore> --fund USDC:3000 \
//     --args 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913 0x4200000000000000000000000000000000000006 \
//     3000000000 2713500000 1105583195135433942 2706750000 <recipient> <refundTo>
import { uniswapV3, uniswapV4 } from "@sauce/router";

// One pool: skipped when missing, empty or already past its own limit, else offered all of the
// budget still unspent, up to its own limit. Returns what it bought.
function trade(
  venue: Uint256, // 0 Uniswap V3, 1 Slipstream, 2 Uniswap V4
  pool: Uint256, // the pool's address; a V4 pool has none, and this is its id, a 256-bit hash
  spacing: Uint256, // a V4 pool's tick spacing
  payToken: Address,
  buyToken: Address,
  kept: Uint256,
  limit: Uint256,
  recipient: Address,
): Uint256 {
  const unspent = Token(payToken).balanceOf(ctx.self()) - kept;
  if (pool == 0 || unspent == 0) {
    return 0;
  }
  const paysToken0 = payToken < buyToken;
  let liquidity = 0;
  let price = 0;
  let fee = 0;
  let lpFee = 0;
  if (venue == 0) {
    liquidity = UniswapV3.Pool(pool).liquidity();
    price = UniswapV3.Pool(pool).slot0().sqrtPriceX96;
    fee = UniswapV3.Pool(pool).fee();
  } else if (venue == 1) {
    // Slipstream's own binding: its slot0 has no feeProtocol, and its fee can change any block.
    liquidity = AerodromeSlipstream.Pool(pool).liquidity();
    price = AerodromeSlipstream.Pool(pool).slot0().sqrtPriceX96;
    fee = AerodromeSlipstream.Pool(pool).fee();
  } else {
    // A missing V4 pool reads as empty. Its fee: this direction's protocol fee (paying token0's in
    // the low 12 bits, token1's in the next 12), then the LP fee on the rest.
    liquidity = UniswapV4.StateView.getLiquidity(pool);
    const [sqrtPriceX96, , protocolFees, poolFee] = UniswapV4.StateView.getSlot0(pool);
    const protocolFee = (paysToken0 ? protocolFees : protocolFees >> 12) & 0xfff;
    price = sqrtPriceX96;
    lpFee = poolFee;
    fee = protocolFee + lpFee - (protocolFee * lpFee) / 1000000;
  }
  // The pool's own limit: the caller's moved by √(1 − fee), so that its last unit, fee paid,
  // costs exactly maxPrice. Paying token0 pushes the price down, token1 pushes it up.
  const root = Math.sqrt((1000000 - fee) * 10 ** 30); // √(1 − fee), times 1e18
  const own = paysToken0 ? Math.mulDiv(limit, 10 ** 18, root) : Math.mulDiv(limit, root, 10 ** 18);
  const better = paysToken0 ? price > own : price < own;
  if (liquidity == 0 || !better) {
    return 0;
  }
  if (venue == 2) {
    // A hookless pool's LP fee is its key's fee.
    const manager = UniswapV4.PoolManager;
    return uniswapV4(manager, payToken, buyToken, unspent, lpFee, spacing, 0, own, 0, recipient);
  }
  // A Slipstream pool swaps and calls back as a Uniswap V3 pool does: uniswapV3 swaps both.
  return uniswapV3(pool, payToken, buyToken, unspent, own, 0, recipient);
}

function main(
  payToken: Address,
  buyToken: Address,
  budget: Uint256,
  maxPrice: Uint256,
  minTokens: Uint256,
  maxAvgPrice: Uint256,
  recipient: Address,
  refundTo: Address,
): { spent: Uint256; bought: Uint256; unspent: Uint256 } {
  const self = ctx.self();
  const pay = payToken;
  require(maxPrice > 0, "maxPrice is 0");
  require(Token(pay).balanceOf(self) >= budget, "budget is not in the Pot");
  const kept = Token(pay).balanceOf(self) - budget; // the Pot's other payToken, never spent
  let bought = 0;

  // maxPrice as a pool's sqrt price (token1 per token0, times 2^96): where a unit costs maxPrice.
  let limit = Math.sqrt(Math.mulDiv(maxPrice, 1 << 192, 10 ** 18));
  if (payToken < buyToken) {
    limit = Math.sqrt(Math.mulDiv(1 << 192, 10 ** 18, maxPrice));
  }

  // The loops only find pools; trade() decides and swaps. Slipstream, keyed by tick spacing.
  for (const spacing of [1, 10, 50, 80, 100, 150, 200, 500, 2000]) {
    const pool = AerodromeSlipstream.CLFactoryGaugesV3.getPool(payToken, buyToken, spacing);
    bought += trade(1, pool, 0, payToken, buyToken, kept, limit, recipient);
  }
  // Uniswap V3, keyed by fee tier: the seven Base's factory enables.
  for (const fee of [100, 200, 300, 400, 500, 3000, 10000]) {
    const pool = UniswapV3.Factory.getPool(payToken, buyToken, fee);
    bought += trade(0, pool, 0, payToken, buyToken, kept, limit, recipient);
  }
  // Uniswap V4, hookless, keyed by fee and tick spacing: the four standard keys. A pool is its id,
  // the hash of its key, the pair in address order: 256 bits, so a Uint256, never an Address.
  const low = payToken < buyToken ? payToken : buyToken;
  const high = payToken < buyToken ? buyToken : payToken;
  for (const key of [
    { fee: 100, spacing: 1 },
    { fee: 500, spacing: 10 },
    { fee: 3000, spacing: 60 },
    { fee: 10000, spacing: 200 },
  ]) {
    const id = crypto.keccak256(abi.encode(low, high, key.fee, key.spacing, 0));
    bought += trade(2, id, key.spacing, payToken, buyToken, kept, limit, recipient);
  }

  // Settle: what was bought is already with the recipient; what is left of the budget goes back.
  const unspent = Token(pay).balanceOf(self) - kept;
  const spent = budget - unspent;
  require(bought >= minTokens, "bought below minTokens");
  require(maxAvgPrice == 0 || spent * 10 ** 18 <= maxAvgPrice * bought, "average too high");
  if (unspent > 0) {
    transfer(pay, refundTo, unspent);
  }
  return { spent, bought, unspent };
}

// @sauce/router — EVM arm. One function per swap venue.
//
// Every function takes RUN-TIME arguments, so a program can choose the pool, the direction and the
// amount while it executes, and every one returns the amount of `tokenOut` the recipient received.
// The arguments come in one order for every venue:
//
//   venue(pool, tokenIn, tokenOut, amountIn, <the venue's own facts>, minOut, recipient)
//
// `pool` is the contract the swap calls: the pair, the pool, the Balancer V2 Vault, the Uniswap V4
// PoolManager. `minOut` is the least the recipient may receive, and below it the whole program
// reverts; `0n` sets no floor, except for `woofi`, which requires one. `recipient` receives the
// output, and `ctx.self()` keeps it in the Pot. Every swap is EXACT INPUT: `amountIn` is what the
// Pot pays, and nothing here can express an exact-output swap.
//
// HOW EACH VENUE IS REACHED.
//
//   - Uniswap V2 (and its forks), Curve, Balancer V2, DODO V2, Trader Joe LB and WOOFi never call
//     back, so these functions call the pool itself: they push the input first (V2, DODO, LB,
//     WooPPV2) or approve exactly the input for the pool to pull (Curve, the Vault). No Router is
//     involved, so they run in any Pot.
//   - Uniswap V3 (and its forks), Uniswap V4, Maverick V2 and PancakeSwap Infinity (CL and bin) pools
//     re-enter their caller mid-swap to be paid. A program cannot answer that call, so these
//     functions call the Pot's Router (`ctx.self()`, whose fallback delegatecalls it), which can.
//     Generation 4 pays only the named input token and only what the pool asks for, up to
//     `amountIn`.
//
// Every token write is `@sauce/token`'s: OpenZeppelin `SafeERC20`, so a token that returns nothing
// (USDT) works, one that returns `false` reverts the program, and an approval resets a standing
// allowance first.
//
// NO REFUND PATH. A function that pushes its input first never catches the pool's failure: each of
// those pools spends everything it is paid or reverts (a V2 pair and a DODO V2 pool book their whole
// balance, LB reverts `LBPair__OutOfLiquidity` rather than fill part of an input, WooPPV2 books
// exactly `fromAmount`), and only an uncaught revert unwinds the push. The `try` functions are the
// one way to get a swap that may fail without reverting the program, and each loses nothing: a
// skipped swap returns `0n` having moved nothing, and a swap that ran returns at least 1, so `0n`
// always means skipped. Three ways make that hold:
//   - a check before anything moves that the pool takes the whole input at the floor —
//     `tryUniswapV2` (the reserves), `tryTraderJoeLB` (`getSwapOut`), `tryDodoV2`
//     (`querySellBase`/`querySellQuote`) and `tryWoofi` (`query`). The swap then runs uncaught, so a
//     failure the check did not foresee still reverts;
//   - catching the pool's failure where the pool pulls the input and enforces the floor itself —
//     `tryCurve` and `tryBalancerV2`, which also reset the approval to zero;
//   - catching the Router's call where the Router pays the pool from inside it — `tryUniswapV3`,
//     `tryUniswapV4`, `tryMaverickV2`, `tryInfinityCL` and `tryInfinityBin`. The generation-4 Router
//     takes no floor, so these hold a swap that ran to the floor afterwards — `minOut`, and at least
//     1 — and revert below it: a swap that took input and delivered nothing (an input the pool rounds
//     away, a hook that keeps it) cannot be undone, so it never reads as skipped. A swap that ran and
//     moved nothing either way (a pool with no liquidity in range) is a skip: the Router's own
//     `amountInUsed`, what it paid out of the Pot, tells the two apart. With no price limit, an
//     empty concentrated-liquidity pool (V3, V4, Infinity CL) costs a full tick walk, millions of
//     gas, before it is skipped; pass a `sqrtPriceLimitX96` to bound it.
//
// ORIENTATION is checked from the arguments while the program runs, so a direction cannot be
// stated backwards. A Uniswap V2 pair's direction IS the sort order of `tokenIn` and `tokenOut`
// (`token0` is the lower address), and so is a Uniswap V4 pool's; DODO V2 takes the pool's base and
// quote tokens and Trader Joe LB its X and Y tokens, and each reverts unless `tokenIn` and `tokenOut`
// are those two. The facts are the caller's: take them from the pool, as you take the pool itself.
//
// No module-level `const` here: a compile-time define replaces a same-named `const` in every module,
// this one included.
import { approve, balanceOf, transfer } from "@sauce/token";
import BalancerV2Vault from "./balancer-v2-vault.abi.json";
import CurveCryptoSwap from "./curve-cryptoswap.abi.json";
import CurveStableSwap from "./curve-stableswap.abi.json";
import DODOV2Pool from "./dodo-v2-pool.abi.json";
import LBPair from "./lb-pair.abi.json";
import MaverickV2Pool from "./maverick-v2-pool.abi.json";
import SauceRouter from "./sauce-router.abi.json";
import SauceRouterPaid from "./sauce-router-paid.abi.json";
import UniswapV2Pair from "./uniswap-v2-pair.abi.json";
import UniswapV3Pool from "./uniswap-v3-pool.abi.json";
import WooPPV2 from "./woo-pp-v2.abi.json";

// ---------------------------------------------------------------------------------------------
// Uniswap V2
// ---------------------------------------------------------------------------------------------

// A Uniswap V2 pair, or a fork's. `feePpm` is the pair's LP fee in parts per million: 3000 (0.30%)
// for Uniswap V2, which `0` also means, and 2500 for PancakeSwap V2; 1_000_000 or more is refused.
// The output is priced from the pair's reserves with the Router's own constant-product math, and
// taken exactly, so the pair's K check holds for a correctly stated fee and reverts for one stated
// too low. The input is pushed first and `swap` called with empty `data` (non-empty data makes the
// pair call `uniswapV2Call` on the recipient). The pair books its whole balance, so it consumes the
// input or reverts — past `uint112`, for one.
export function uniswapV2(
  pair: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  feePpm: Uint256,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  require(feePpm < 1000000n);
  let fee = feePpm;
  if (fee == 0n) {
    fee = 3000n;
  }
  const zeroForOne = tokenIn < tokenOut;
  const [reserve0, reserve1, updated] = UniswapV2Pair.at(pair).getReserves();
  let reserveIn = reserve1;
  let reserveOut = reserve0;
  if (zeroForOne) {
    reserveIn = reserve0;
    reserveOut = reserve1;
  }
  const inWithFee = amountIn * (1000000n - fee);
  const out = Math.mulDiv(inWithFee, reserveOut, reserveIn * 1000000n + inWithFee);
  require(out >= minOut);
  transfer(tokenIn, pair, amountIn);
  let amount0Out = out;
  let amount1Out = 0n;
  if (zeroForOne) {
    amount0Out = 0n;
    amount1Out = out;
  }
  const data = hex``;
  UniswapV2Pair.at(pair).swap(amount0Out, amount1Out, recipient, data);
  return out;
}

// `uniswapV2`, or nothing: `0n` with nothing moved when the pair cannot take the whole input — no
// input, an input its reserve cannot hold (past `uint112`), or an output of zero or below the floor.
// Otherwise the swap runs uncaught, so a failure the check did not foresee still reverts.
export function tryUniswapV2(
  pair: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  feePpm: Uint256,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  require(feePpm < 1000000n);
  let fee = feePpm;
  if (fee == 0n) {
    fee = 3000n;
  }
  const zeroForOne = tokenIn < tokenOut;
  const [reserve0, reserve1, updated] = UniswapV2Pair.at(pair).getReserves();
  let reserveIn = reserve1;
  let reserveOut = reserve0;
  if (zeroForOne) {
    reserveIn = reserve0;
    reserveOut = reserve1;
  }
  // type(uint112).max: a pair's reserve refuses to grow past it. Checked before the math, which an
  // input that large would overflow.
  if (amountIn == 0n || amountIn > 5192296858534827628530496329220095n - reserveIn) {
    return 0n;
  }
  const inWithFee = amountIn * (1000000n - fee);
  const out = Math.mulDiv(inWithFee, reserveOut, reserveIn * 1000000n + inWithFee);
  if (out == 0n || out < minOut) {
    return 0n;
  }
  transfer(tokenIn, pair, amountIn);
  let amount0Out = out;
  let amount1Out = 0n;
  if (zeroForOne) {
    amount0Out = 0n;
    amount1Out = out;
  }
  const data = hex``;
  UniswapV2Pair.at(pair).swap(amount0Out, amount1Out, recipient, data);
  return out;
}

// ---------------------------------------------------------------------------------------------
// Curve
// ---------------------------------------------------------------------------------------------

// A Curve pool's 4-argument `exchange(i, j, dx, min_dy)`, after an approval of exactly the input,
// which the pool pulls. `i`/`j` are the coins' indices; `uint256Indices` picks the CryptoSwap
// spelling (uint256 indices) over the StableSwap and StableSwap-NG one (int128), and `minOut` is
// the pool's own `min_dy`. `exchange`'s output is not decoded, because a 3pool-era pool returns none:
// what was received is the Pot's `tokenOut` balance delta, forwarded when the recipient is not the
// Pot.
export function curve(
  pool: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  i: Uint256,
  j: Uint256,
  uint256Indices: bool,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  approve(tokenIn, pool, amountIn);
  const before = balanceOf(tokenOut, ctx.self());
  if (uint256Indices) {
    CurveCryptoSwap.at(pool).exchange(i, j, amountIn, minOut);
  } else {
    CurveStableSwap.at(pool).exchange(i, j, amountIn, minOut);
  }
  const out = balanceOf(tokenOut, ctx.self()) - before;
  if (recipient != ctx.self()) {
    transfer(tokenOut, recipient, out);
  }
  return out;
}

// `curve`, or nothing: a failed `exchange` is caught, the approval reset to zero, and `0n` returned
// with nothing moved. The pool's floor is at least 1, so a swap that ran never reads as skipped.
export function tryCurve(
  pool: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  i: Uint256,
  j: Uint256,
  uint256Indices: bool,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  let floor = minOut;
  if (floor == 0n) {
    floor = 1n;
  }
  approve(tokenIn, pool, amountIn);
  const before = balanceOf(tokenOut, ctx.self());
  let failed = false;
  if (uint256Indices) {
    CurveCryptoSwap.at(pool)
      .exchange(i, j, amountIn, floor)
      .catch(() => {
        failed = true;
      });
  } else {
    CurveStableSwap.at(pool)
      .exchange(i, j, amountIn, floor)
      .catch(() => {
        failed = true;
      });
  }
  if (failed) {
    approve(tokenIn, pool, 0n);
    return 0n;
  }
  // A swap that ran delivered something: the pool's own floor is at least 1.
  const out = balanceOf(tokenOut, ctx.self()) - before;
  require(out > 0n);
  if (recipient != ctx.self()) {
    transfer(tokenOut, recipient, out);
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// Balancer V2
// ---------------------------------------------------------------------------------------------

// One Balancer V2 pool, through its Vault (`pool` is the Vault, `poolId` the pool's 32-byte id): an
// approval of exactly the input, then `Vault.swap` GIVEN_IN with `minOut` as the Vault's own limit
// and internal balances off. The Vault pays the recipient and returns the amount.
export function balancerV2(
  vault: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  poolId: Uint256,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  approve(tokenIn, vault, amountIn);
  const userData = hex``;
  // The deadline is the largest uint256: the swap runs in this transaction or not at all.
  return BalancerV2Vault.at(vault).swap(
    {
      poolId: poolId,
      kind: 0n,
      assetIn: tokenIn,
      assetOut: tokenOut,
      amount: amountIn,
      userData: userData,
    },
    {
      sender: ctx.self(),
      fromInternalBalance: false,
      recipient: recipient,
      toInternalBalance: false,
    },
    minOut,
    115792089237316195423570985008687907853269984665640564039457584007913129639935n,
  );
}

// `balancerV2`, or nothing: a failed `Vault.swap` is caught, the approval reset to zero, and `0n`
// returned with nothing moved. The Vault's limit is at least 1, so a swap that ran never reads as
// skipped.
export function tryBalancerV2(
  vault: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  poolId: Uint256,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  let floor = minOut;
  if (floor == 0n) {
    floor = 1n;
  }
  approve(tokenIn, vault, amountIn);
  const userData = hex``;
  const out = BalancerV2Vault.at(vault)
    .swap(
      {
        poolId: poolId,
        kind: 0n,
        assetIn: tokenIn,
        assetOut: tokenOut,
        amount: amountIn,
        userData: userData,
      },
      {
        sender: ctx.self(),
        fromInternalBalance: false,
        recipient: recipient,
        toInternalBalance: false,
      },
      floor,
      115792089237316195423570985008687907853269984665640564039457584007913129639935n,
    )
    .catch(() => {
      return 0n;
    });
  if (out == 0n) {
    approve(tokenIn, vault, 0n);
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// DODO V2
// ---------------------------------------------------------------------------------------------

// A DODO V2 pool (DVM, DPP or DSP), given its `_BASE_TOKEN_()` and `_QUOTE_TOKEN_()`: push the input,
// then `sellBase(to)` when it is the base token or `sellQuote(to)` when it is the quote token. The
// side cannot come from address order, and the wrong one does not revert — the pool prices the
// side it was told to sell, sees none of it, and keeps the push — so this reverts unless `tokenIn`
// and `tokenOut` are the base and quote tokens, in either order. The pool books its whole balance,
// so it consumes the input or reverts.
export function dodoV2(
  pool: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  baseToken: Address,
  quoteToken: Address,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  const sellBase = tokenIn == baseToken && tokenOut == quoteToken;
  require(sellBase || (tokenIn == quoteToken && tokenOut == baseToken));
  transfer(tokenIn, pool, amountIn);
  let out = 0n;
  if (sellBase) {
    out = DODOV2Pool.at(pool).sellBase(recipient);
  } else {
    out = DODOV2Pool.at(pool).sellQuote(recipient);
  }
  require(out >= minOut);
  return out;
}

// `dodoV2`, or nothing: `0n` with nothing moved unless the pool's own `querySellBase`/
// `querySellQuote` view, read before anything moves, prices the whole input at the floor (and at
// least 1). A pool with no code, or whose view reverts (an empty side, a zero guide price, an input
// past what its curve can price), is skipped too. Otherwise the swap runs uncaught, so a failure the
// check did not foresee still reverts. The view is asked for `ctx.self()`'s fee; the pool charges the
// transaction's origin, which a program cannot read, so where its fee model tells the two apart the
// swap can deliver other than the quote, and below the floor it reverts.
export function tryDodoV2(
  pool: Address,
  tokenIn: Address,
  tokenOut: Address,
  amountIn: Uint256,
  baseToken: Address,
  quoteToken: Address,
  minOut: Uint256,
  recipient: Address,
): Uint256 {
  require(tokenIn != tokenOut);
  const sellBase = tokenIn == baseToken && tokenOut == quoteToken;
  require(sellBase || (tokenIn == quoteToken && tokenOut == baseToken));
  if (amountIn == 0n || ctx.codeSize(pool) == 0n) {
    return 0n;
  }
  let floor = minOut;
  if (floor == 0n) {
    floor = 1n;
  }
  let quoted = 0n;
  if (sellBase) {
    quoted = DODOV2Pool.at(pool)
      .querySellBase(ctx.self(), amountIn)
      .catch(() => {
        return 0n;
      });
  } else {
    quoted = DODOV2Pool.at(pool)
      .querySellQuote(ctx.self(), amountIn)
      .catch(() => {
        return 0n;
      });
  }
  if (quoted < floor) {
    return 0n;
  }
  transfer(tokenIn, pool, amountIn);
  let out = 0n;
  if (sellBase) {
    out = DODOV2Pool.at(pool).sellBase(recipient);
  } else {
